  [6205] = { "I danni fisici inflitti dal bersaglio sono ridotti di $N1 per $D1. Su un bersaglio può essere attiva solo una maledizione per Stregone alla volta.", "Danni fisici inflitti ridotti di $N1.", 0x45b27a1b, 0x21281ce3, "uu" },
  [6213] = { "Incute paura al nemico, costringendolo a fuggire per un massimo di $D1. Eventuali danni inflitti al bersaglio potrebbero interrompere l'effetto. Può essere spaventato solo $N2 bersaglio alla volta.", "Impaurito.", 0xc6065f5d, 0x5a2205f2, "uu" },
  [6215] = { "Incute paura al nemico, costringendolo a fuggire per un massimo di $D1. Eventuali danni inflitti al bersaglio potrebbero interrompere l'effetto. Può essere spaventato solo $N2 bersaglio alla volta.", "Impaurito.", 0xc6065f5d, 0x5a2205f2, "uu" },
  [6217] = { "Affligge il bersaglio con l'agonia, infliggendo $N1 danni da ombra in $D1. All'inizio i danni sono inflitti lentamente e aumentano man mano che l'anatema si avvicina alla sua durata massima. Su un bersaglio può essere attivo solo un anatema per Stregone alla volta.", { "$N1 danni da ombra in $D1.", shape = { "2/1" } }, 0xd5b9a42b, 0x13d78fd1, "uu" },
